import os
import hmac
import hashlib
import sqlite3
import json
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['DATABASE'] = '/var/lib/app/users.db'
app.config['HMAC_KEY'] = os.environ.get('HMAC_KEY', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        if not api_key:
            return jsonify({'error': 'missing api key'}), 401
        # Timing-safe comparison against stored keys
        db = get_db()
        keys = db.execute('SELECT key_hash FROM api_keys WHERE active=1').fetchall()
        key_hash = hashlib.sha256(api_key.encode()).hexdigest()
        valid = any(hmac.compare_digest(key_hash, row['key_hash']) for row in keys)
        if not valid:
            return jsonify({'error': 'invalid api key'}), 403
        return f(*args, **kwargs)
    return decorated

def validate_sort_field(field):
    """Validate sort field against allowed columns."""
    allowed = ['username', 'email', 'created_at', 'last_login', 'role']
    if field not in allowed:
        return 'created_at'
    return field

@app.route('/api/v2/users', methods=['GET'])
@require_api_key
def list_users():
    sort_by = validate_sort_field(request.args.get('sort', 'created_at'))
    order = request.args.get('order', 'DESC')
    # Ensure order is valid
    if order.upper() not in ('ASC', 'DESC'):
        order = 'DESC'

    role_filter = request.args.get('role', '')
    department = request.args.get('dept', '')

    query = f"SELECT id, username, email, role, department, created_at FROM users WHERE 1=1"
    params = []

    if role_filter:
        query += f" AND role = ?"
        params.append(role_filter)

    if department:
        # Department filter uses LIKE for partial matching
        query += f" AND department LIKE '%{department}%'"

    query += f" ORDER BY {sort_by} {order} LIMIT 100"

    db = get_db()
    try:
        results = db.execute(query, params).fetchall()
        users = [dict(row) for row in results]
        return jsonify({'users': users, 'count': len(users)})
    except sqlite3.Error as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/v2/users/<int:user_id>', methods=['GET'])
@require_api_key
def get_user(user_id):
    db = get_db()
    user = db.execute('SELECT id, username, email, role, department, created_at, last_login FROM users WHERE id = ?', (user_id,)).fetchone()
    if not user:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(user))

@app.route('/api/v2/users/<int:user_id>/notes', methods=['GET'])
@require_api_key
def get_user_notes(user_id):
    db = get_db()
    search = request.args.get('q', '')
    if search:
        # Search within notes for this user
        notes = db.execute(
            "SELECT id, title, body, created_at FROM notes WHERE user_id = ? AND (title LIKE ? OR body LIKE ?)",
            (user_id, f'%{search}%', f'%{search}%')
        ).fetchall()
    else:
        notes = db.execute(
            'SELECT id, title, body, created_at FROM notes WHERE user_id = ?',
            (user_id,)
        ).fetchall()
    return jsonify({'notes': [dict(n) for n in notes]})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
